75: const TOKEN_KEY = 'flood-token-v1'
76: export function getToken(): string | undefined {
77:   try { const t = uni.getStorageSync(TOKEN_KEY); return typeof t === 'string' && t ? t : undefined } catch { return undefined }
78: }
79: export function setToken(token: string) { try { uni.setStorageSync(TOKEN_KEY, token) } catch { /* ignore */ } }
80: export function clearToken() { try { uni.removeStorageSync(TOKEN_KEY) } catch { /* ignore */ } }
