[{"type":"text","text":"# 鑻忎綇鎴块槻姹汣绔紙uni-app H5锛夋湰鍦?nginx 閮ㄧ讲
# 鏋勫缓浜х墿锛欴:/repository/鑻忎綇鎴块槻姹汣绔?dist锛坣pm run test / uni build -m test --outDir ./dist锛?# 鐢?nginx.conf 鐨?include conf.d/*.conf 鑷姩鍔犺浇锛屾棤闇€鏀瑰姩涓婚厤缃€?#
# 绔彛璇存槑锛氬師鐢?8103 + default_server锛屼笌 sites-enabled/鏄嗗北鐗╃.conf锛堟槅灞盙锛?# listen 8103 server_name localhost锛夋姠鍗狅紝涓?default_server 浼氳鎵€鏈夊叾瀹?Host
# 鐨?8103 璇锋眰閮借惤鍒版湰鏈嶅姟涓婏紝褰卞搷鏄嗗北椤圭洰銆傛晠鏀瑰埌绌洪棽绔彛 8095 骞跺幓鎺?default_server銆?server {
    listen 8095;
    server_name localhost;
    root "D:/repository/鑻忎綇鎴块槻姹汣绔?dist";
    index index.html;
    charset utf-8;

    # 闈欐€佽祫婧愰暱缂撳瓨锛宨ndex.html 寮哄埗涓嶈蛋缂撳瓨锛岄伩鍏嶅彂鐗堝悗 chunk 404
    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map)$ {
        expires 7d;
        add_header Cache-Control "public" always;
        access_log off;
        try_files $uri =404;
    }

    location = /index.html {
        expires -1;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
    }

    # 鍙嶅悜浠ｇ悊锛?api/ 杞彂鑻忎綇鎴?dev 缃戝叧锛堝惈鐧诲綍 /v2.0/code銆?v2.0/security/auth/login锛?    location /api/ {
        proxy_pass http://unlimited.c.h5.query.mobile.v2.suzhufang.shiqu.suzhou.dev.zhi.com;
        proxy_http_version 1.1;
        proxy_set_header Host unlimited.c.h5.query.mobile.v2.suzhufang.shiqu.suzhou.dev.zhi.com;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # uni-app H5 浣跨敤 hash 璺敱锛屽洖閫€鍒?index.html 鍗冲彲
    location / {
        try_files $uri $uri/ /index.html;
    }
}
"}]

