2: import { defineStore } from 'pinia'
3: import { saveDemoPhoto } from '../utils/photo'
4: export interface Photo { id: string; source: string; url: string; status: 'saving' | 'done' | 'failed'; error?: string; name?: string }
5: export function createPhotoStore(save: (path: string) => Promise<string>, id = 'photos', maxCount = 6) {
6:   return defineStore(id, () => {
7:     const items = ref<Photo[]>([])
8:     async function retry(id: string) {
9:       const photo = items.value.find(item => item.id === id)
10:       if (!photo) return
11:       photo.status = 'saving'; photo.error = ''
12:       try { photo.url = await save(photo.source); photo.status = 'done' }
13:       catch (error) { photo.status = 'failed'; photo.error = error instanceof Error ? error.message : '照片保存失败' }
14:     }
15:     async function add(paths: string[]) {
16:       if (items.value.length + paths.length > maxCount) throw new Error(`最多${maxCount}张`)
17:       const photos: Photo[] = paths.map(source => ({ id: `photo-${Date.now()}-${Math.random().toString(36).slice(2)}`, source, url: '', status: 'saving' }))
18:       items.value.push(...photos)
19:       await Promise.all(photos.map(photo => retry(photo.id)))
20:     }
21:     function remove(id: string) { items.value = items.value.filter(item => item.id !== id) }
22:     function readyPhotos() {
23:       if (items.value.some(item => item.status !== 'done')) throw new Error('请等待照片保存完成，失败照片请重试或删除')
24:       return items.value.map(item => ({ ...item }))
25:     }
26:     function restore(photos: Photo[]) { items.value = photos.map(item => ({ ...item })) }
27:     return { items, add, retry, remove, readyPhotos, restore }
28:   })
29: }
