// ============================================================
// 物业标准化评价（项目检查 / 4 类检查）本地演示数据集
// 仅用于 demo 构建（VITE_EVALUATION_MOCK=true）下让「物业自查」
// 相关的全部 UI 都能看到对应展示：工作台入口 → 记录列表（统计 /
// 待办任务 / 已完成记录）→ 发起检查（区域搜索 / 检查信息）→
// 检查填写（五类逐项打分 / 整体情况 / 整改通知书）→ 检查记录详情
// （检查详情 / 整改详情 / 整改反馈 / 整改报告）。
// 数据结构严格对齐 src/types/evaluation.ts，页面与 store 无需改动分支。
// ============================================================
import type {
  CheckStat, CheckRecordRow, CheckTaskRow, ComplexRow, ComplexInfo,
  CheckForm, CheckDetail, RectifyDetail, RectifyItem, CategoryGroup,
  ProjectGroup, CheckItem, ScoreOption, CheckType,
} from '../types/evaluation'
import { serviceTypeNames } from '../types/evaluation'

/** 演示种子版本：结构调整时 +1，可让本地已缓存数据失效 */
export const EVALUATION_MOCK_SEED_VERSION = 3

const DEMO_PHOTO = '/static/assets/e3436.png'
const photos = (n = 2) => Array.from({ length: n }, () => DEMO_PHOTO).join(',')

/** 演示当前时间基准（相对"今天"漂移，保证列表永远有本月/本年度数据） */
function daysAgo(n: number): string {
  const d = new Date()
  d.setDate(d.getDate() - n)
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
}
const YEAR = String(new Date().getFullYear())

// ------------------------------------------------------------
// 1) 可选物业管理区域（发起检查 - 已备案等级区域，带检查信息）
// ------------------------------------------------------------
interface DemoComplex extends ComplexRow {
  info: ComplexInfo
}

const COMPLEXES: DemoComplex[] = [
  makeComplex({
