function clone<T>(v: T): T { return JSON.parse(JSON.stringify(v)) as T }

function makeComplex(input: Record<string, string | number> & { complexId: string; complexName: string; region: string; regionName: string; subdistrict: string; subdistrictName: string; community: string; communityName: string; address: string }): DemoComplex {
  const get = (k: string) => String(input[k] ?? '')
  return {
    complexId: input.complexId, complexName: input.complexName, complexCode: get('complexCode'), companyName: get('companyName'),
    region: input.region, regionName: input.regionName, subdistrict: input.subdistrict, subdistrictName: input.subdistrictName,
    community: input.community, communityName: input.communityName, address: input.address,
    info: {
      complexId: input.complexId, complexName: input.complexName, regionCode: input.region, regionName: input.regionName,
      subdistrictCode: input.subdistrict, subdistrictName: input.subdistrictName, communityCode: input.community, communityName: input.communityName,
      companyId: get('companyId'), companyName: get('companyName'), hasContract: get('hasContract') || '1', contractTip: get('contractTip'),
      evalLevel: get('evalLevel'), evalLevelName: get('evalLevelName'), checkFrequency: get('checkFrequency'), checkFrequencyName: get('checkFrequencyName'),
      checkedCount: Number(input.checkedCount ?? 0),
      gradeComprehensiveLevel: '2', gradeFacilityLevel: '2', gradeOrderLevel: '2', gradeCleanLevel: '2', gradeGreeningLevel: '2',
      canStart: get('hasContract') !== '0', cannotStartReason: get('hasContract') === '0' ? get('contractTip') : '',
    },
  }
}

