interface BuildFormInput {
  checkRecordId: string; recordCode: string; checkType: CheckType
  complexId: string; complexName: string; regionName: string; subdistrictName: string; communityName: string
  companyName: string; evalLevel: string; evalLevelName: string; checkFrequencyName: string; checkTime: string; bizState: string
  filled?: boolean
}

/** 五类服务 × 每类若干项目/检查项；filled=true 时回填得分/说明/图片并从扣分项汇总整改数 */
function buildForm(i: BuildFormInput): CheckForm {
  const filled = i.filled === true
  const categoryList: CategoryGroup[] = SERVICE_TEMPLATE.map((catTpl, ci) => {
    const projectList: ProjectGroup[] = catTpl.projects.map((projTpl, pi) => {
      const itemList: CheckItem[] = projTpl.items.map((contentName, ii) => {
        const top = projTpl.score
        const deduct = filled && (ci === 1 && pi === 0 && ii === 0 || ci === 3 && pi === 0 && ii === 1)
        const itemScore = filled ? (deduct ? top - 2 : top) : null
        const optionList: ScoreOption[] = [
          { optionId: `${ci}-${pi}-${ii}-a`, optionName: '符合', score: top },
          { optionId: `${ci}-${pi}-${ii}-b`, optionName: '基本符合', score: top - 2 },
          { optionId: `${ci}-${pi}-${ii}-c`, optionName: '不符合', score: 0 },
        ]
        return {
          checkItemId: `CI-${ci}-${pi}-${ii}`, contentId: `CT-${ci}-${pi}-${ii}`, categoryId: `CAT-${ci}`,
          projectId: `PJ-${ci}-${pi}`, contentName, score: top, itemScore,
          isNotApplicable: '0', remark: deduct ? `现场检查发现：${contentName}未达标，需整改。` : '',
          images: deduct ? photos(2) : '', sortOrder: ii + 1, optionList,
          serviceType: String(ci + 1),
        }
      })
      const actual = itemList.reduce((s, it) => s + Number(it.itemScore ?? 0), 0)
      return { projectId: `PJ-${ci}-${pi}`, projectName: projTpl.name, projectScore: itemList.reduce((s, it) => s + Number(it.score), 0), actualScore: filled ? actual : 0, itemList }
    })
    const itemCount = projectList.reduce((s, p) => s + p.itemList.length, 0)
    const checkedCount = filled ? itemCount : 0
    const totalScore = projectList.reduce((s, p) => s + Number(p.projectScore), 0)
    const actualScore = projectList.reduce((s, p) => s + Number(p.actualScore), 0)
    return {
      serviceType: String(ci + 1), serviceName: serviceTypeNames[String(ci + 1)], standardId: `STD-${ci + 1}`,
      standardName: `${serviceTypeNames[String(ci + 1)]}服务标准`, evalLevel: i.evalLevel, evalLevelName: i.evalLevelName,
      totalScore, actualScore: filled ? actualScore : 0, itemCount, checkedCount,
      finished: filled, projectList,
    }
  })
  const finishedCount = filled ? categoryList.length : 0
  let actualScore = categoryList.reduce((s, c) => s + Number(c.actualScore), 0)
  if (filled) actualScore = 82 // 与列表 finalScore 一致
  return {
    checkRecordId: i.checkRecordId, recordCode: i.recordCode, checkType: i.checkType, checkTypeName: '物业自查',
    complexId: i.complexId, complexName: i.complexName, regionName: i.regionName, subdistrictName: i.subdistrictName,
    communityName: i.communityName, companyName: i.companyName, evalLevel: i.evalLevel, evalLevelName: i.evalLevelName,
    checkFrequencyName: i.checkFrequencyName, checkTime: i.checkTime, bizState: i.bizState, levelEditable: false,
    gradeComprehensiveLevel: i.evalLevel, gradeFacilityLevel: i.evalLevel, gradeOrderLevel: i.evalLevel,
    gradeCleanLevel: i.evalLevel, gradeGreeningLevel: i.evalLevel,
    finishedCount, totalCount: categoryList.length, progressPercent: Math.round((finishedCount / categoryList.length) * 100),
    standardTotalScore: categoryList.reduce((s, c) => s + Number(c.totalScore), 0), actualScore,
    situationDesc: filled ? '本期自查总体情况良好，消防通道畅通，设施设备运行正常；共用部位存在少量墙面破损与绿化补植不足，已列入整改。' : '',
    signCompanyLeader: filled ? DEMO_PHOTO : '', signInspector: filled ? DEMO_PHOTO : '',
    attachment: filled ? photos(2) : '', isGenerateNotice: filled ? '1' : '',
    rectifyDeadline: filled ? daysAgo(-2) : '',
    abnormalNotInvestigate: filled ? 1 : 0, abnormalNoEvidence: 0, abnormalUnclosed: filled ? 1 : 0, abnormalOther: 0,
    categoryList,
  }
}

function buildRectifyItems(): RectifyItem[] {
  const out: RectifyItem[] = []
  const cats = SERVICE_TEMPLATE.map((c, ci) => ({ ci, c }))
  for (const { ci, c } of cats) {
    for (const [pi, proj] of c.projects.entries()) {
      for (const [ii, contentName] of proj.items.entries()) {
        const deduct = ci === 1 && pi === 0 && ii === 0 || ci === 3 && pi === 0 && ii === 1
        if (!deduct) continue
        out.push({
          rectificationItemId: `RI-${ci}-${pi}-${ii}`, serviceName: serviceTypeNames[String(ci + 1)], projectName: proj.name,
          contentName, score: proj.score, itemScore: proj.score - 2,
